var FO = window.__FO || (window.__FO = {});

FO.scene = function(id, whip){
  MSD.cls('.fo-sc', 'on', false);
  MSD.cls('#fo-sc-' + id, 'on', true);
  MSD.cls('#fo-sc-' + id, 'whip', false);
  if(whip) MSD.after(20, function(){ MSD.cls('#fo-sc-' + id, 'whip', true); MSD.sfx.swipe(); });
};

FO.header = function(app, amount, tone, health){
  MSD.q('#fo-app').textContent = app;
  MSD.q('#fo-rt-n').textContent = amount;
  MSD.cls('#fo-rt', 'bad', tone === 'bad');
  MSD.cls('#fo-rt', 'ok', tone === 'ok');
  MSD.cls('#fo-health', 'bad', tone === 'bad');
  MSD.cls('#fo-health', 'warn', tone === 'warn');
  MSD.q('#fo-health-t').textContent = health;
};

FO.strip = function(id, label, text, tone){
  MSD.cls(id, 'bad', tone === 'bad');
  MSD.cls(id, 'warn', tone === 'warn');
  MSD.cls(id, 'good', tone === 'good');
  MSD.q(id + '-l').textContent = label;
  MSD.q(id + '-t').textContent = text;
};

/** The processed-order row: which chip is the one that should not be there. */
FO.processed = function(a, b, c, badIndex){
  var t = [a, b, c];
  ['#fo-o-1', '#fo-o-2', '#fo-o-3'].forEach(function(sel, i){
    MSD.q(sel).textContent = t[i];
    MSD.cls(sel, 'bad', i === badIndex);
    MSD.cls(sel, 'ok', badIndex === -1);
  });
};

FO.cfg = function(id, key, value, sub, tone){
  MSD.cls(id, 'bad', tone === 'bad');
  MSD.cls(id, 'good', tone === 'good');
  MSD.q(id + '-k').textContent = key;
  MSD.q(id + '-v').textContent = value;
  MSD.q(id + '-s').textContent = sub;
};

FO.scene('cart');
FO.header('cart-4471 · 3 events', '$0', '', 'in order');
MSD.cls('.fo-ev', 'hot', false);
MSD.cls('.fo-ev', 'bad', false);
MSD.cls('#fo-receipt', 'on', false);
FO.strip('#fo-strip', 'THREE EVENTS', 'One cart, three events, published in the order they happened.', '');

MSD.after(400, function(){ MSD.cls('#fo-ev-1', 'hot', true); MSD.sfx.blip(0); });
MSD.after(900, function(){ MSD.cls('#fo-ev-2', 'hot', true); MSD.sfx.blip(1); });
MSD.after(1400, function(){ MSD.cls('#fo-ev-3', 'hot', true); MSD.sfx.blip(2); });
MSD.after(2100, function(){
  FO.strip('#fo-strip', 'SIMPLE', 'Added, removed, checked out. The basket is empty when they pay.', 'good');
  MSD.punch('#fo-expect', 3);
  MSD.sfx.lock();
});

var FO = window.__FO;

FO.scene('cart');
FO.header('cart-4471 · 3 events', '$0', '', 'in order');
MSD.cls('.fo-ev', 'hot', true);
MSD.cls('#fo-receipt', 'on', false);
FO.strip('#fo-strip', 'SIMPLE', 'Added, removed, checked out. The basket is empty when they pay.', 'good');

MSD.after(700, function(){
  MSD.cls('#fo-receipt', 'on', true);
  FO.header('cart-4471 · charged', '$120', 'bad', 'wrong total');
  MSD.punch('#fo-receipt', 4);
  MSD.sfx.thud();
